s=s.replace('let mut public:[u8;16]=kani::any();', 'let mut public:[u8;1880]=kani::any();')
s=s.replace('let mut checkpoint=vec![0u8;CP];\n let occupied:bool=kani::any();if occupied {checkpoint[0]=1;}', 'let mut checkpoint=[0u8;CP];')
